// "What's new in Forever" comparison. Bundled data is generated by `npm run changes`; the desktop app rebuilds it
// from Settings → Check for updates whenever the Forever data changes, and the downloaded copy takes priority.
import BUNDLED from './classChanges.json' with { type: 'json' };

const override = (() => {
  try {
    const data = globalThis.everhart?.getChangesOverride?.();
    return data?.classes && data?.meta ? data : null;
  } catch {
    return null;
  }
})();

export const CHANGES = override ?? BUNDLED;
export const CHANGES_META = { ...CHANGES.meta, origin: override ? 'downloaded' : 'bundled' };
